import{_ as a,o as l,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"Североамериканская плюралистическая цивилизация","description":"","frontmatter":{},"headers":[],"relativePath":"ru/0033-北美多元型文明.md","filePath":"ru/0033-北美多元型文明.md"}'),o={name:"ru/0033-北美多元型文明.md"};function e(n,t,d,h,s,u){return l(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="североамериканская-плюралистическая-цивилизация" tabindex="-1">Североамериканская плюралистическая цивилизация <a class="header-anchor" href="#североамериканская-плюралистическая-цивилизация" aria-label="Permalink to &quot;Североамериканская плюралистическая цивилизация&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>33</td></tr><tr><td>Модуль</td><td>Типы цивилизаций и социальные системы</td></tr><tr><td>Ключевые слова</td><td>Североамериканский плюралистический, Свобода и разнообразие, Равные возможности, Рыночная конкуренция, Инновационный драйв</td></tr></tbody></table><h2 id="i-происхождение-и-ядро-идеи" tabindex="-1">I. Происхождение и ядро идей <a class="header-anchor" href="#i-происхождение-и-ядро-идеи" aria-label="Permalink to &quot;I. Происхождение и ядро идей&quot;">​</a></h2><p>Североамериканский плюралистический — самый свободный из пяти типов; истоки — в традициях Северной Америки реального мира (США, Канада). Веками складывались черты: свобода личности, рыночная конкуренция, плюрализм. После основания Симбиотической Цивилизации Якоря традиция соединилась с идеями симбиоза — родился тип.</p><p>Ядро — двенадцать иероглифов: «свобода и разнообразие, равенство возможностей». Подробно:</p><ol><li><strong>Свобода личности</strong>: высшая ценность; каждый культиватор вправе выбирать систему, путь, образ жизни, организацию — без вмешательства</li><li><strong>Плюрализм</strong>: уважение и терпимость к различиям рас, культур, вер, укладов; равное сосуществование разных рас и систем</li><li><strong>Равенство возможностей</strong>: при разрывах богатства и уровней — равный старт; рождение и статус не барьер</li><li><strong>Конкуренция и инновация</strong>: свободная конкуренция будит потенциал и творчество; оптимальное распределение и инновации</li></ol><p>Совместимо с ядром: «само-рост» — свобода и ответственность; «Путь для Каждого» — равенство возможностей; «Больше Труда — Больше Награды» — честная конкуренция.</p><h2 id="ii-социальная-структура" tabindex="-1">II. Социальная структура <a class="header-anchor" href="#ii-социальная-структура" aria-label="Permalink to &quot;II. Социальная структура&quot;">​</a></h2><p>«Слабое государство + сильное общество + рыночная экономика + сеть безопасности»:</p><table tabindex="0"><thead><tr><th>Элемент</th><th>Характеристика</th><th>Функция</th></tr></thead><tbody><tr><td>Слабое государство</td><td>Ограничено размером и функциями; порядок и блага</td><td>Базовая институциональная рамка</td></tr><tr><td>Сильное общество</td><td>НКО, общины, группы интересов развиты</td><td>Самоуправление и услуги</td></tr><tr><td>Рыночная экономика</td><td>Рынок распределяет большую часть</td><td>Эффективное распределение</td></tr><tr><td>Сеть безопасности</td><td>Ограниченная защита слабых</td><td>Права на жизнь и развитие</td></tr></tbody></table><h3 id="_2-1-слабое-государство" tabindex="-1">2.1 Слабое государство <a class="header-anchor" href="#_2-1-слабое-государство" aria-label="Permalink to &quot;2.1 Слабое государство&quot;">​</a></h3><p>Типичное «ограниченное государство»:</p><ul><li>Порядок и безопасность; жизнь и имущество</li><li>Блага: якоря, каналы, законы</li><li>Рыночный порядок; против монополий</li><li>Сеть безопасности для слабых</li></ul><p>Ядро — «государство — ночной сторож общества»; не вмешивается в жизнь, но даёт рамку.</p><h3 id="_2-2-сильное-общество" tabindex="-1">2.2 Сильное общество <a class="header-anchor" href="#_2-2-сильное-общество" aria-label="Permalink to &quot;2.2 Сильное общество&quot;">​</a></h3><ul><li><strong>Общины</strong>: автономия, услуги, взаимопомощь</li><li><strong>Профессиональные ассоциации</strong>: стандарты, сертификация, обмен</li><li><strong>Группы интересов</strong>: защита прав коллективным действием</li><li><strong>Фонды и благотворительность</strong>: наука, образование, благо</li></ul><p>«Малое государство, большое общество».</p><h3 id="_2-3-рыночная-экономика" tabindex="-1">2.3 Рыночная экономика <a class="header-anchor" href="#_2-3-рыночная-экономика" aria-label="Permalink to &quot;2.3 Рыночная экономика&quot;">​</a></h3><ul><li><strong>Собственность</strong>: защита имущества и достижений</li><li><strong>Конкуренция</strong>: свободный вход-выход, поток ресурсов</li><li><strong>Договор</strong>: добровольные контракты, исполнение</li><li><strong>Предпринимательство</strong>: риск, терпимость к неудаче</li></ul><p>Цена, конкуренция, стимул — эффективное распределение.</p><h2 id="iii-модель-культивации" tabindex="-1">III. Модель культивации <a class="header-anchor" href="#iii-модель-культивации" aria-label="Permalink to &quot;III. Модель культивации&quot;">​</a></h2><p>«Свободный выбор, конкурентный отбор, разнообразие путей»:</p><h3 id="_3-1-свободныи-выбор" tabindex="-1">3.1 Свободный выбор <a class="header-anchor" href="#_3-1-свободныи-выбор" aria-label="Permalink to &quot;3.1 Свободный выбор&quot;">​</a></h3><p>Триста Изначальных Систем открыты всем; выбор по интересам, таланту, целям. Нет «стандартного пути» — каждый свой.</p><h3 id="_3-2-конкурентныи-отбор" tabindex="-1">3.2 Конкурентный отбор <a class="header-anchor" href="#_3-2-конкурентныи-отбор" aria-label="Permalink to &quot;3.2 Конкурентный отбор&quot;">​</a></h3><p>Свобода — да, конкуренция — да; честная, прозрачная, по правилам:</p><ul><li>Квоты ресурсов</li><li>Поступление в секты и академии</li><li>Поля продвижения</li><li>Посты в крупных проектах</li></ul><h3 id="_3-3-разнообразие-путеи" tabindex="-1">3.3 Разнообразие путей <a class="header-anchor" href="#_3-3-разнообразие-путеи" aria-label="Permalink to &quot;3.3 Разнообразие путей&quot;">​</a></h3><ul><li>Секта, академия, самостоятельность, наставник, гибрид — любой</li><li>Выбор по обстоятельствам; максимум потенциала</li></ul><h3 id="_3-4-культура-инновации" tabindex="-1">3.4 Культура инноваций <a class="header-anchor" href="#_3-4-культура-инновации" aria-label="Permalink to &quot;3.4 Культура инноваций&quot;">​</a></h3><p>Новые методы, энергия, технологии; патенты и почести — щедрые награды.</p><h2 id="iv-подряд-связанныи-с-результатом" tabindex="-1">IV. Подряд, связанный с результатом <a class="header-anchor" href="#iv-подряд-связанныи-с-результатом" aria-label="Permalink to &quot;IV. Подряд, связанный с результатом&quot;">​</a></h2><p>«Рыночный подряд»:</p><ol><li><strong>Индивид</strong>: прямое соглашение, ясные права и долг</li><li><strong>Рынок</strong>: доход по спросу и предложению</li><li><strong>Сеть безопасности</strong>: ограниченная защита слабых</li><li><strong>Предпринимательский возврат</strong>: риск — возврат</li></ol><p>Плюс: инициатива, творчество, эффективность; минус — разрыв богатства; сеть держит стабильность.</p><h2 id="v-преимущества-и-вызовы" tabindex="-1">V. Преимущества и вызовы <a class="header-anchor" href="#v-преимущества-и-вызовы" aria-label="Permalink to &quot;V. Преимущества и вызовы&quot;">​</a></h2><h3 id="_5-1-преимущества" tabindex="-1">5.1 Преимущества <a class="header-anchor" href="#_5-1-преимущества" aria-label="Permalink to &quot;5.1 Преимущества&quot;">​</a></h3><ul><li><strong>Инновация</strong>: среда стимулирует</li><li><strong>Жизненность</strong>: плюрализм и конкуренция</li><li><strong>Свобода</strong>: потенциал по воле</li><li><strong>Притяжение</strong>: таланты со вселенной</li></ul><h3 id="_5-2-вызовы" tabindex="-1">5.2 Вызовы <a class="header-anchor" href="#_5-2-вызовы" aria-label="Permalink to &quot;5.2 Вызовы&quot;">​</a></h3><ul><li><strong>Разрыв богатства</strong>: растёт, бьёт по равенству</li><li><strong>Слабая сплочённость</strong>: индивидуализм против общины</li><li><strong>Коммерциализация</strong>: рынок в не-рынок</li><li><strong>Слабая база</strong>: сеть не спасает всех</li></ul><p>Ответ: вбирает лучшее — всеобщую защиту североевропейского, коллективную координацию восточноазиатского.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Самый свободный тип: «свобода и разнообразие, равенство возможностей»; слабое государство, сильное общество, рынок, сеть; свободный выбор; рыночный подряд. Сохраняя своё, ищет баланс свободы и порядка, конкуренции и сотрудничества.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>30-五种共生文明分型总览 (Обзор пяти типов симбиотических цивилизаций)</li><li>34-欧洲大陆社会型文明 (Континентально-европейская социальная цивилизация)</li><li>36-社会结构与阶层流动 (Социальная структура и мобильность классов)</li></ul>',45)])])}const c=a(o,[["render",e]]);export{_ as __pageData,c as default};
